mapper.select:
select
(select count(*) from Oa_Annual_Plan_Change_Dtl where Apc_Id=mn.Id) as dtlCount,
(select count(*) from Oa_Annual_Plan_Change_Dtl where Apc_Id=mn.Id and Apd_Type='1') as addCount,
(select count(*) from Oa_Annual_Plan_Change_Dtl where Apc_Id=mn.Id and Apd_Type='2') as delCount,
mn.*
from Oa_Annual_Plan_Change mn

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Ap_Id=#{params.apId}
    
    
        and mn.Ap_Year=#{params.apYear}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and INSTR(mn.Ap_Title,#{params.apTitle})
    
    
        and INSTR(mn.Ap_Remark,#{params.apRemark})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
